        /// <summary>
        /// Rnder report content
        /// </summary>
        /// <param name="template"></param>
        private void RenderReportContent(WinlossByBetTypeAgent_ExcelContents_Block excelBlock)
        {
            DataTable reportData = View as DataTable;

            // Render date from and date to
            RenderReportContentHeader(excelBlock);

            excelBlock.Content.Clear();
            int numRow = reportData.Rows.Count;
            if (numRow > 0)
            {
                WinlossByBetTypeAgent_ExcelContents_Content_Block rowBlock = new WinlossByBetTypeAgent_ExcelContents_Content_Block();
                WinlossByBetTypeAgent_LocalControl_CasinoLink_Block casinoLink = new WinlossByBetTypeAgent_LocalControl_CasinoLink_Block();
                WinlossByBetTypeAgent_LocalControl_BingoLink_Block bingoLink = new WinlossByBetTypeAgent_LocalControl_BingoLink_Block();

                // The column name for master and super is different
                for (int i = 0; i < numRow; i++)
                {
                    DataRow dr = reportData.Rows[i];
                    int betType = Convert.ToInt32(dr["bettype"]);
                    string betTypeName = Sunplus.Agent.Model.BL.Cache.CacheRef.GetBettype(dr["bettype"]);

                    switch (betType)
                    {
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Casino_Games:  // 71
                            {
                                casinoLink.BetTypeName = betTypeName;
                                casinoLink.CasinoType = "Casino";
                                rowBlock.BetTypeName = casinoLink.ToString();
                            }
                            break;
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.P2P: // 1000
                            {
                                //casinoLink.BetTypeName = Resources.Lang.P2P;
                                //casinoLink.CasinoType = "P2P";
                                rowBlock.BetTypeName = Resources.Lang.P2P;
                            }
                            break;
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Bingo: // 73
                            {
                                bingoLink.BetTypeName = betTypeName;
                                rowBlock.BetTypeName = bingoLink.ToString();
                            }
                            break;
                        case (int)(Sunplus.Agent.Model.BL.Definitions.BetType.N_Over_Under): // Number game Over/Under
                            rowBlock.BetTypeName = Resources.Lang.next + " " + betTypeName + " (" + Resources.Lang.numbergame + ")";
                            break;
                        case (int)(Sunplus.Agent.Model.BL.Definitions.BetType.N_Odd_Even): // Number game Odd/Even
                            string strNextCombo = (int)dr["liveindicator"] == 1 ? Resources.Lang.next + " " : Resources.Lang.ft + ". ";
                            rowBlock.BetTypeName = strNextCombo + betTypeName + " (" + Resources.Lang.numbergame + ")";
                            break;
                        case (int)(Sunplus.Agent.Model.BL.Definitions.BetType.NumberWheel): // Number game - NumberWheel
                            string typeNumberWheel = (int)dr["liveindicator"] == 1 ? Resources.Lang.LiveGame : Resources.Lang.PreGame;
                            rowBlock.BetTypeName = betTypeName + " (" + typeNumberWheel + ")";
                            break;
                        // For Live Casino
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Baccarat: // 1101
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Roulette: // 1102
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.Sicbo: // 1103
                            {
                                if (UserPermission.IsShowLiveCasino)
                                {
                                    rowBlock.BetTypeName = betTypeName;
                                    break;
                                }
                                else
                                    continue;
                            }
                        // For Virtual Sports
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_1X2:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_CorrectScore:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_DoubleChange:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_Handicap:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_OverUnder:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VS_TotalGoal:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VHR_Win:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VHR_Place:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VHR_WinPlace:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VHR_Forecast:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VHR_Tricast:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VT_PlayerWin:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VT_ScoreBet:
                        case (int)Sunplus.Agent.Model.BL.Definitions.BetType.VT_TotalPoints:
                            rowBlock.BetTypeName = betTypeName + " (" + Resources.Lang.VirtualSports + ")";
                            break;
                        default:
                            rowBlock.BetTypeName = betTypeName;
                            break;
                    }

                    rowBlock.ColorClass = (i % 2 == 0) ? EVEN_ROW_CLASS : ODD_ROW_CLASS;

                    rowBlock.GrossComm = Formater.DecFormat(dr["GrossComm"], 2);
                    rowBlock.NoOfTicket = dr["noofticket"].ToString();
                    rowBlock.Turnover = Formater.DecFormat(dr["turnover"], 2);
                    rowBlock.WinlossMem = Formater.DecFormat(dr["memberwinlost"], 2);
                    rowBlock.ComMem = Formater.DecFormat(dr["playercomm"], 2);
                    rowBlock.TotalMem = Formater.DecFormat(dr["membertotal"], 2);
                    rowBlock.WinlossAgent = Formater.DecFormat(dr["agwinlost"], 2);
                    rowBlock.ComaAgent = Formater.DecFormat(dr["agcomm"], 2);
                    rowBlock.TotalAgent = Formater.DecFormat(dr["agtotal"], 2);
                    rowBlock.Company = Formater.DecFormat(dr["company"], 2);

                    // Add row
                    excelBlock.Content.Append(rowBlock);
                }

                // Total row
                excelBlock.TotalContent.NoOfTicket = reportData.Compute("SUM(noofticket)", "").ToString();
                excelBlock.TotalContent.GrossComm = Formater.DecFormat(reportData.Compute("SUM(GrossComm)", ""), 2);
                excelBlock.TotalContent.Turnover = Formater.DecFormat(reportData.Compute("SUM(turnover)", ""), 2);
                excelBlock.TotalContent.WinlossMem = Formater.DecFormat(reportData.Compute("SUM(memberwinlost)", ""), 2);
                excelBlock.TotalContent.CommMem = Formater.DecFormat(reportData.Compute("SUM(playercomm)", ""), 2);
                excelBlock.TotalContent.TotalMem = Formater.DecFormat(reportData.Compute("SUM(membertotal)", ""), 2);
                excelBlock.TotalContent.WinlossAgent = Formater.DecFormat(reportData.Compute("SUM(agwinlost)", ""), 2);
                excelBlock.TotalContent.ComAgent = Formater.DecFormat(reportData.Compute("SUM(agcomm)", ""), 2);
                excelBlock.TotalContent.TotalAgent = Formater.DecFormat(reportData.Compute("SUM(agtotal)", ""), 2);
                excelBlock.TotalContent.Company = Formater.DecFormat(reportData.Compute("SUM(company)", ""), 2);

                // Hide noinfo row
                excelBlock.NoInfo.Hide();
            }
            else
            {
                excelBlock.TotalContent.Hide();
                excelBlock.NoInfo.NoInfoRow.NumCols = "11";
            }
        }

        private void RenderReportTimeDisclaimer(WinlossByBetTypeAgent_Template template)
        {
            template.ReportSearchHeader.SetReportTimeDisclaimer(string.Format(Resources.Lang.ViewDataFromDate, MinReportDateString));
        }

        #endregion Render Utility
    }
